import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易集说卷二十七","description":"周易集说 - 周易集说卷二十七","frontmatter":{"title":"周易集说卷二十七","description":"周易集说 - 周易集说卷二十七"},"headers":[],"relativePath":"zh/classics/jishuo/028.md","filePath":"zh/classics/jishuo/028.md"}'),r={name:"zh/classics/jishuo/028.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易集说卷二十七" tabindex="-1">周易集说卷二十七 <a class="header-anchor" href="#周易集说卷二十七" aria-label="Permalink to “周易集说卷二十七”">​</a></h1><p>钦定四库全书</p><p>宋俞琰撰</p><p>坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎水天而时行。</p><p>天属乾阳而刚，地属坤阴而柔。地体虽柔，动而生物，其用则刚。坤卦六爻纯乎阴柔，是为至柔。动则变为乾阳而刚，故曰「坤至柔而动也刚」。地虽动而生物，其体本静，坤卦六爻纯乎阴静，是为至静。唯其至静，所以其德方正而截然不易，故曰「至静而德方」。天数居始而为一，地数居次而为二，坤道之常。盖当处后，不可搀先也。搀先则失坤道之常矣。唯处乾之后，顺乾而行，则得其所主，而不失坤道之常也。故曰「后得主而有常」。含，藏蓄也。万物无大无小，地皆藏蓄于其中，博厚之至也。阳变而阴化，天施而地生。坤之含万物，仅能化生耳。非若乾之能变而又能化，能施而又能生也。故孔子于乾言变化，于坤但言化而不言变。盖乾能兼坤，坤仅得乾之半也。「光」，谓地道之光。阳明而阴暗，坤阴物安得光？横渠张子曰：「效法故光。」汉上朱子曰：「坤之光，即乾之光。」愚谓坤本无光，动而从乾，是以光也。「顺」，谓顺乾而行也。承天，谓天气在上，而降施于地，地则顺承而受之也。「时行」，谓以时而行。时乎春夏，而天气发生，则地气亦为之发生；时乎秋冬，而天气收敛，则地气亦为之收敛。坤之为道，盖如此其顺也。此章申彖传之意，所谓「至柔而动也刚」，申「德合无疆」之义。「至静而德方」，释「贞」义。「后得主而有常」，后顺得常之谓。「含万物而化光」，即「含弘光大，品物咸亨」之谓。「坤道其顺乎，承天而时行」，即「乃顺承天」之谓。自此以后，皆申爻传之义。或疑文言传两赞用九，至用六则无一语及之。殊不思「坤至柔而动也刚」，此非赞用六而何？洪容斋曰：顷见僧昙莹云：「动者，谓爻之变也。坤不动则已，动则阳刚见焉。在初为复，在二为师，在三为谦。自是而往，皆刚也。」其说最为分明有理。愚谓昙莹所云，不过谓一爻之动耳。坤爻传所为六二之动是也。今曰「坤至柔而动也刚」，盖谓六爻俱动，而至柔之坤，变纯刚之乾，非但为一爻之动也。</p><p>积善之家，必有余庆。积不善之家，必有余殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辩之不早辩也。易曰：「履霜坚冰至。」盖言顺也。坤之初六，阴柔不中不正，不善也。不善之积极而至于弑君弑父，实从此始。以积善并言，盖明善不善皆在所积。天道福善祸淫，作善则降之百祥，作不善则降之百殃。苟积善，则不独身受其福，又福于而家，以及其子孙，是谓余庆；积不善，则不独身受其祸，又祸于而家，以及其子孙，是谓余殃。必者，祸福之应，如影随形，如响随声，理之所必然也。积善而曰必有余庆，所以劝天下忠臣孝子，而使之勉于为善也。积不善而曰必有余殃，所以惧天下乱臣贼子，而使之不敢为恶也。乃臣弑君，子弑父，岂一朝一夕之故？原其所由来，则自小而大，从微而著，如霜而至于冰，皆以渐而积也。辩，察也。由辩之不早辩，盖罪其君父之不明。明者知渐不可积，于是防其微而辩之于早，故天下之恶无由而成，盖知霜冰之戒也。若小恶不遏，坐视其长，则末流之弊有不可胜言者，是谁之过欤？由君宠其臣而不早辩其臣之恶，父宠其子而不早辩其子之恶故也。盖言「顺也」之顺，与前坤道其顺乎之顺不同。盖谓事势之顺，不知不觉，积渐因循而至于此极也。积不善，申「履霜阴凝」之义。弑君弑父，申「至坚冰」之义。「非一朝一夕之故」，申「驯致其道」之义也。诚斋杨氏曰：「顺当作驯。」紫阳朱子曰：「古字顺、慎通用。」</p><p>直其正也，方其义也。君子敬以直内，义以方外。敬义立而德不孤。「直方大，不习无不利」，则不疑其所行也。发明六二之「直方」，而曰</p><p>「直其正也，方其义也」，则下文当曰「正以直内，义以方外」。今乃曰「敬以直内」，而不曰「正以直内」，何也？或曰：刘元城尝改「敬以直内」为「正以直内」矣。然正无下功夫处，故须敬。言敬则正在其中，敬则有所操守，而不失其本然之正也。或又曰：礼记云「直其正也」，「政」乃「敬」之讹尔。「敬」讹为「政」，「政」又转而为「正」，亦犹诗「体无咎言」，礼记乃云「履无咎言」。「体」讹为「礼」，「礼」又转而为「履」，理或然也。敬者，主一于此而无他适之谓。义者，裁制于彼而合其宜之谓。敬以操守于内，而心不他适，则其直于内也，洞然而略无私曲。义以裁制于外，而事皆合宜，则其方于外也，截然而不可移易。君子盖无往而非敬，无往而非义也。「敬义立」谓内不枉己，外不徇物，而卓然自立也。二所主者敬，而义则自此而出焉，故有内外之辩。敬在是则义在是，内直则外自方，非谓敬必在内，义必在外也。「德不孤」谓择善而得所从也。六二在群阴之中，不与群阴为党，其势似孤，其德则不孤。盖以敬义自立，舍坤阴从乾阳，又焉得孤？「不疑」，谓择善之明而不惑也。坤德虽柔顺，而六二所行者正，不习初六之阴邪，则其从乾阳而行也，夫复何疑？此章以敬释「直」字，义释「方」字，又以「敬以直内」是持守功夫，「义以方外」是讲学功夫。从程子、朱子之说，则坤六二之所谓「不习」，可以为不学乎？平庵项氏曰：习，重习也。二之所习，谓习初也。地利。阴邪不可使盛，若朋类相习，积阴不已，则贼乱之所由兴也。初、二一阴方生，圣人积虑其习，曰积、曰渐、曰驯、曰顺，皆深绝之。六二之阴瀳至，位当重习，独能不习，故圣人喜之。盖初不正而二正，初不中而二中，每事相反而不相重，是以知其不习也。又曰：阴与阴相敌则孤，孤则小；阴从阳则不孤，不孤则大。妇能如此，则得乎夫；臣能如此，则得乎君。皆阴德之不孤者也。张播本「直方大」上有「易曰」二字。</p><p>阴虽有美，含之以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成而代有终也。阴从阳而不敢专也，故虽有美，亦含之而不发也。以，用也。或用之从王事，则归美于君，弗敢以成功自居，故曰</p><p>「阴虽有美，含之以从王事，弗敢成也」。弗敢成者，非其才之不足而不能成也，为下之道当如是也。伊川程子曰：「如是则上无忌恶之心，下得恭顺之道也。」愚谓下之事上，犹阴之从阳，便观地之承天可见。乃若妻之从夫，臣之从君，皆此道也。故曰「地道也，妻道也，臣道也」。不言子道，臣与子一也。夫天气降而至于地，地中生物者皆天之气，地唯顺而承之，不敢居其成功，是谓「地道无成」。既曰「地道无成」，而又曰「代有终」，何也？曰：天数止乎九，是无终也；地数终于十，则有终矣。是故乾能始物，不能终物。坤继其终而终之，则坤之所以为有终者，终乾之所未终也。坤不有其成而有其终，故曰「地道无成而代有终」也。代，继也。古之人为臣而尽臣道者，以地道自处，而不矜不伐，唯知代天之功以终其劳。及其成功，则归之天，不敢贪天之功以为己力，盖知「地道无成而代有终」之义也。美释「章」字，以妻道、臣道并言，盖申无成有终之义。此独言「地道」，则举其大者尔。书君陈云：「尔有嘉谋嘉猷，则入告尔后于内，尔乃顺之于外，曰：斯谋斯猷，惟我后之德。呜呼！」臣人咸若是，惟良显哉！其「坤」六三之谓欤！</p><p>天地变化，草木蕃，天地闭，贤人隐。易曰：「括囊，无咎无誉。」盖言谨也。</p><p>「乾」阳用事，则「天地变化，草木蕃，贤人出」。「坤」阴用事，则「天地闭，贤人隐」。当此「天地闭，贤人隐」之时，一语之差，则凶祸随至，不谨密可乎？易之所谓「括囊，无咎无誉」，盖言君子之谨密，不可不如是也。且夫「乾」之初九，在下卦之下，去九五之君甚远，其隐宜乎？「坤」之六四在上卦之下，居近君之地，而乃隐焉，何也？曰：「坤」六五亦臣也，非君也。以人臣而处君位，与「乾」九五异矣。而六四适近之，此六四大不幸也。「乾」九五在上，而天地闭塞，天下终有战争之祸，则六四以隐为咎。盖时异事殊，君子亦唯随时之治乱以为进退也。时当进，君子亦进，「乾」九五是也。时当隐，君子亦隐，「坤」六四是也。「谨」，即慎不害之谓。曰「闭」、曰「隐」，皆释「括囊」之义也。</p><p>君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。</p><p>「黄中」，谓君子有中德之美也。「通理」，谓通达乎道理也。「正位」，谓知君臣之大义，而以正上下之名位也。「居体」，谓以臣道自居，而不失为下之体也。「美在其中，而畅于四支」，以至发为事业，尽有可观，岂非美之至乎？「正位居体」，盖「坤」之正位在六二，而六五非正，是宜正之也。「坤」之体当居下，而居上非所宜也。「黄中通理，正位居体」，释「黄裳元吉」之义。美在其中，畅于四支，发于事业。释文「在中」之义。「黄中通理」，以身言，故曰「四支」。「居」者，身居之也。「黄中」故能「正位」，「通理」故能「居体」。或者难曰：六十四卦皆以五为君，九居五为刚中之君，六居五为柔中之君，今乃以坤之六爻全为臣道，无乃不可乎？愚曰：不然，易中以六居五，盖半矣。莫非君也，在「泰」在「大有」之类，则为谦顺之君。在「离」在「未济」之类，则为文明之君。在「豫」在「恒」之类，则为暗弱之君。惟「坤」之五虽君位，「坤」实臣道，不济不取君义，此童溪王氏之说也。「坤」之六爻，皆顺承乾五之一君，故「坤」之五不得为君，此诚斋杨氏之说也。窃谓六十四卦自贞而下，阴阳相杂，刚柔相交，始有所谓阴阳之配应，刚柔之乘承。于是「乾」则全卦皆为君德，而「乾」之九二，其位虽臣，其德则君也。「坤」则全卦皆为臣道，而「坤」之六五，其位虽君，其道则臣也。岂可与诸卦例言哉？</p><p>阴疑于阳必战，为其嫌于无阳也，故称「龙」焉。犹未离其类也，故称「血」焉。夫</p><p>「玄黄」者，天地之杂也。天玄而地黄。疑，谓似也。坤至上六，阴盛而与阳相似也。阴当从阳也，盛极则不能降以相从也，不相从则与阳为敌，故曰「阴疑于阳必战」。乾，君象也，故乾之彖传谓乾之六爻为六龙。龙，君象。坤乃臣，而上六亦称龙，何也？圣人以坤之上六，处臣道之盛极，而天下不知有君，故特以龙言。故曰：「为其嫌于无阳也，故称龙焉」。为，去声。尔雅云：「十月为阳。」郑玄曰：「十月纯坤用事，嫌于无阳，故名此月为阳。」天道不可一日无阳，人道不可一日无君也。节初齐氏曰：盖与春秋天王狩于河阳同一书法。狩于河阳，非天王，而曰天王，嫌于无王也。圣人于阳亦然。血，阴物也。臣虽强，不离阴类，故曰「犹未离其类也，故称血焉」。离，去声。玄者，天之色；黄者地之色。血言「玄黄」，则天地杂类而阴阳无别矣。故曰「夫玄黄者，天地之杂也」。阴阳相战，虽至于天地之杂乱，然而天地定位于上下，其大分终不可易，故其中又分而言之曰：「天玄而地黄」。周易集说卷二十七，</p>',16)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
